window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-137"]=[{"id":"set2-aj4TvlKy","fingerprint":"3c246d7a6c8a61db","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care dintre următoarele afecțiuni este considerată o contraindicație absolută pentru extracția dentară?","options":[{"id":"A","text":"Tumorile maligne în teritoriul oro-maxilo-facial"},{"id":"B","text":"Sinuzita maxilară rinogenă"},{"id":"C","text":"Stomatita herpetică"},{"id":"D","text":"Abcesul periosos"},{"id":"E","text":"Infarctul miocardic recent (mai recent de 6 luni)"}],"correct":["E"],"pages":[568],"source":"set-2"},{"id":"set2-cb-3e7x1","fingerprint":"8249d77d3f059368","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect managementul contraindicațiilor relative ale extracției dentare?","options":[{"id":"A","text":"Se referă exclusiv la afecțiuni precum leucemia acută și infarctul miocardic recent."},{"id":"B","text":"Pot necesita aplicarea unui tratament specific pentru afecțiunea locală."},{"id":"C","text":"Sunt considerate obstacole insurmontabile, impunând anularea permanentă a extracției."},{"id":"D","text":"Pot necesita compensarea afecțiunii generale de către medicul specialist."},{"id":"E","text":"Implică temporizarea extracției dentare."}],"correct":["B","D","E"],"pages":[568],"source":"set-2"},{"id":"set2-CEd_EyNY","fingerprint":"205b6a3687b8a27d","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce atitudine terapeutică este indicată în cazul unui pacient cu flegmon, înainte de a se efectua o extracție dentară cauzală?","options":[{"id":"A","text":"Efectuarea imediată a extracției, deoarece flegmonul este o contraindicație absolută."},{"id":"B","text":"Realizarea extracției sub protecție de antibiotic, fără a drena colecția."},{"id":"C","text":"Tratarea flegmonului de către medicul specialist și apoi anularea permanentă a extracției."},{"id":"D","text":"Administrarea de antiinflamatoare și extracția dintelui în aceeași ședință."},{"id":"E","text":"Drenajul colecției supurative și temporizarea extracției până la remiterea fenomenelor inflamatorii acute."}],"correct":["E"],"pages":[568],"source":"set-2"},{"id":"set2-rVnuJV9I","fingerprint":"be27d908280bd52a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele sunt considerate contraindicații relative locale pentru extracția dentară?","options":[{"id":"A","text":"Celulita"},{"id":"B","text":"Pericoronarita"},{"id":"C","text":"Aftele"},{"id":"D","text":"Leucemia acută"},{"id":"E","text":"Infarctul miocardic cu o vechime de 1 an"}],"correct":["A","B","C"],"pages":[568],"source":"set-2"},{"id":"set2-maxsRps2","fingerprint":"78da099b2d34dc1a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afecțiuni reprezintă contraindicații relative locale pentru o extracție dentară?","options":[{"id":"A","text":"Diatezele hemoragice"},{"id":"B","text":"Tumorile maligne în teritoriul oro-maxilo-facial"},{"id":"C","text":"Cardiopatia ischemică"},{"id":"D","text":"Stomatita candidozică"},{"id":"E","text":"Sinuzita maxilară rinogenă"}],"correct":["B","D","E"],"pages":[569],"source":"set-2"},{"id":"set2-zgZVnjKT","fingerprint":"3fb08a04af07e02f","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce recomandare specifică privind anestezia se aplică pacienților cu cardiopatie ischemică sau hipertensiune arterială care necesită o extracție dentară?","options":[{"id":"A","text":"Efectuarea sistematică a extracțiilor sub anestezie generală."},{"id":"B","text":"Administrarea preoperatorie a unui medicament anxiolitic puternic."},{"id":"C","text":"Efectuarea extracțiilor cu anestezie locală fără vasoconstrictori."},{"id":"D","text":"Utilizarea anesteziei locale cu o concentrație crescută de vasoconstrictori."},{"id":"E","text":"Amânarea extracției până la normalizarea completă a funcției cardiace."}],"correct":["C"],"pages":[569],"source":"set-2"},{"id":"set2-TxIOG81k","fingerprint":"6f749f1fa1eee343","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este ținta principală a antibioprofilaxiei în cazul procedurilor stomatologice invazive?","options":[{"id":"A","text":"Virusurile herpetice latente."},{"id":"B","text":"Stafilococii de pe tegument."},{"id":"C","text":"Bacteriile anaerobe din pungile parodontale."},{"id":"D","text":"Candida albicans."},{"id":"E","text":"Streptococii orali."}],"correct":["E"],"pages":[569],"source":"set-2"},{"id":"set2-ynOk7i_0","fingerprint":"74179c6e7c78bf4e","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"În care dintre următoarele situații este indicată antibioprofilaxia endocarditei infecțioase?","options":[{"id":"A","text":"Pacienți cu endocardită infecțioasă în antecedente."},{"id":"B","text":"Pacienți cu proteză valvulară, inclusiv proteze transcateter."},{"id":"C","text":"Pacienți cu hipertensiune arterială controlată medicamentos."},{"id":"D","text":"Afecțiuni cardiace congenitale cianogene netratate."},{"id":"E","text":"Afecțiuni cardiace congenitale corectate chirurgical fără defecte reziduale, la 1 an postoperator."}],"correct":["A","B","D"],"pages":[569],"source":"set-2"},{"id":"set2-alvsYrnS","fingerprint":"9611c65c6c9a28f3","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care este protocolul standard de antibioprofilaxie a endocarditei bacteriene pentru un adult fără alergii cunoscute?","options":[{"id":"A","text":"Ceftriaxonă 2 g, în doză unică, intravenos, cu 30 de minute înainte de intervenție."},{"id":"B","text":"Amoxicilină 2 g, în doză unică, per os, cu o oră înaintea extracției."},{"id":"C","text":"Administrarea intravenoasă a Amoxicilinei se face cu 30 de minute înainte de intervenție."},{"id":"D","text":"Clindamicină 600 mg, în doză unică, per os, cu o oră înaintea extracției."},{"id":"E","text":"Amoxicilină 50 mg/kg, în doză unică, per os, cu o oră înainte de intervenție."}],"correct":["B","C"],"pages":[569],"source":"set-2"},{"id":"set2-KQJVcjQo","fingerprint":"d2de8a61a36cc0ae","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce protocol de antibioprofilaxie se recomandă pentru un pacient cu antecedente de anafilaxie la penicilină?","options":[{"id":"A","text":"Cefazolină 1 g."},{"id":"B","text":"Ceftriaxonă 1 g."},{"id":"C","text":"Ampicilină 2 g."},{"id":"D","text":"Amoxicilină 2 g."},{"id":"E","text":"Clindamicină 600 mg."}],"correct":["E"],"pages":[569],"source":"set-2"},{"id":"set2-IFy7Qa_b","fingerprint":"5cedd8b723b3f479","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele reprezintă cauze ale purpurelor vasculare?","options":[{"id":"A","text":"Mecanisme autoimune, cum ar fi în purpura reumatoidă Schoenlein-Henoch."},{"id":"B","text":"Paraproteinemia, cum ar fi în purpura crioglobulinemică."},{"id":"C","text":"Un defect cantitativ al trombocitelor (trombocitopenie)."},{"id":"D","text":"Infecții virale, cum ar fi gripa, rujeola sau rubeola."},{"id":"E","text":"Malformații de structură ale vaselor sanguine, precum în telangiectazia hemoragică ereditară Osler-Weber-Rendu."}],"correct":["A","B","D","E"],"pages":[569],"source":"set-2"},{"id":"set2-Zq7Burvp","fingerprint":"b9f536708e84261d","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"În ce situații care impun temporizarea extracției este necesar mai întâi drenajul colecției supurative?","options":[{"id":"A","text":"Pericoronarite"},{"id":"B","text":"Flegmoane"},{"id":"C","text":"Celulită periosoasă"},{"id":"D","text":"Afte bucale recurente"},{"id":"E","text":"Stomatită herpetică"}],"correct":["A","B","C"],"pages":[569],"source":"set-2"},{"id":"set2-s9v7096a","fingerprint":"fb9cb261824b524a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele categorii reprezintă tulburări ale hemostazei primare?","options":[{"id":"A","text":"Purpurele trombocitopenice (trombocitopenii)"},{"id":"B","text":"Purpurele vasculare (vasculopatii)"},{"id":"C","text":"Coagulopatiile ereditare"},{"id":"D","text":"Trombocitopatiile"},{"id":"E","text":"Deficitul ereditar de factor VIII"}],"correct":["A","B","D"],"pages":[570],"source":"set-2"},{"id":"set2-mOwcMH55","fingerprint":"26b7d508f968cc9d","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce afecțiuni sunt clasificate drept purpure vasculare determinate de malformații de structură ale vaselor sanguine?","options":[{"id":"A","text":"Purpura senilă"},{"id":"B","text":"Purpura reumatoidă Schoenlein-Henoch"},{"id":"C","text":"Sindromul Waterhouse-Friderichsen"},{"id":"D","text":"Sindromul Marfan"},{"id":"E","text":"Telangiectazia hemoragică ereditară Osler-Weber-Rendu"}],"correct":["A","D","E"],"pages":[570],"source":"set-2"},{"id":"set2-Lqfwg3ft","fingerprint":"76011ecfcd295d54","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"La ce valoare a numărului de trombocite se definește o purpură trombocitopenică?","options":[{"id":"A","text":"&lt; 10.000/mm³"},{"id":"B","text":"≤ 100.000/mm³"},{"id":"C","text":"≤ 25.000/mm³"},{"id":"D","text":"≤ 50.000/mm³"},{"id":"E","text":"≤ 150.000/mm³"}],"correct":["D"],"pages":[570],"source":"set-2"},{"id":"set2-8m6yG-dv","fingerprint":"571f7d2db7015d60","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afecțiuni sau condiții duc la purpură trombocitară prin producție scăzută de trombocite?","options":[{"id":"A","text":"Lupusul eritematos sistemic (LES)"},{"id":"B","text":"Pancitopenia Fanconi"},{"id":"C","text":"Splenomegalia"},{"id":"D","text":"Anemiile megaloblastice prin deficit de vitamina B12/acid folic"},{"id":"E","text":"Sindromul Wiskott-Aldrich"}],"correct":["B","D","E"],"pages":[570],"source":"set-2"},{"id":"set2-ol0HHUlq","fingerprint":"d0ec6b6e492741da","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele mecanisme pot duce la purpură trombocitară prin consum excesiv al trombocitelor?","options":[{"id":"A","text":"Infecțiile virale cu HIV sau CMV"},{"id":"B","text":"Prezența protezelor valvulare"},{"id":"C","text":"Hipoplazia medulară idiopatică"},{"id":"D","text":"Coagularea intravasculară diseminată (sindromul CID)"},{"id":"E","text":"Purpura trombocitopenică trombotică Moschowitz"}],"correct":["B","D","E"],"pages":[570],"source":"set-2"},{"id":"set2-Ohvugzya","fingerprint":"ac76487941171053","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce afecțiuni reprezintă trombocitopatii primare (genetice)?","options":[{"id":"A","text":"Insuficiența renală cronică în stadiul uremic"},{"id":"B","text":"Trombastenia Glanzmann"},{"id":"C","text":"Sindromul Wiskott-Aldrich"},{"id":"D","text":"Boala Bernard-Soulier"},{"id":"E","text":"Gamapatiile monoclonale"}],"correct":["B","D"],"pages":[570],"source":"set-2"},{"id":"set2-GKbcOd1V","fingerprint":"eb44ab3dfd7c94e9","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce medicamente pot induce trombocitopatii prin interferarea cu calea de sinteză a prostaglandinelor?","options":[{"id":"A","text":"Propranololul"},{"id":"B","text":"Antiagregantele plachetare"},{"id":"C","text":"AINS (antiinflamatoare nesteroidiene)"},{"id":"D","text":"Aspirina"},{"id":"E","text":"Cafeina"}],"correct":["B","C","D"],"pages":[570],"source":"set-2"},{"id":"set2-FCK_sh0i","fingerprint":"912b2eaf5169568a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este asocierea corectă între tipul de hemofilie și deficitul specific de factor de coagulare?","options":[{"id":"A","text":"Hemofilia B - deficit de factor VIII"},{"id":"B","text":"Hemofilia A - deficit de factor VIII"},{"id":"C","text":"Boala Hageman - deficit de factor VIII"},{"id":"D","text":"Hemofilia B - deficit de factor XI"},{"id":"E","text":"Hemofilia A - deficit de factor IX"}],"correct":["B"],"pages":[570],"source":"set-2"},{"id":"set2-ZUi_ENTw","fingerprint":"a899267a07004faa","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Un pacient cu hemofilie care prezintă hemoragii spontane are, cel mai probabil, ce concentrație a factorului de coagulare deficitar?","options":[{"id":"A","text":"&gt; 25%"},{"id":"B","text":"≤ 5%"},{"id":"C","text":"≤ 10%"},{"id":"D","text":"&lt; 1%"},{"id":"E","text":"≤ 25%"}],"correct":["D"],"pages":[570],"source":"set-2"},{"id":"set2-_-C3r3Fu","fingerprint":"c7085a1b79b5cf44","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele condiții pot fi considerate cauze ale coagulopatiilor secundare?","options":[{"id":"A","text":"Deficitul genetic de factor von Willebrand (FvW), care stabilizează factorul procoagulant VIII."},{"id":"B","text":"Hemoragii asociate cu post-transfuzii masive."},{"id":"C","text":"Deficitul de sinteză a factorilor de coagulare dependenți de vitamina K, cum se întâlnește în sindroamele colestatice."},{"id":"D","text":"Formarea de anticorpi specifici împotriva factorilor de coagulare precum F VIII și factorul von Willebrand."},{"id":"E","text":"Consumul rapid al factorilor de coagulare, cum ar fi în coagularea intravasculară diseminată."}],"correct":["B","C","D","E"],"pages":[571],"source":"set-2"},{"id":"set2-LmyEfrYz","fingerprint":"0d9aa12be2c3802e","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce funcții îndeplinește factorul von Willebrand (FvW) în procesul de hemostază?","options":[{"id":"A","text":"Inhibă factorul X activat, oprind cascada coagulării."},{"id":"B","text":"Este un anticorp specific care neutralizează factorul VII al coagulării."},{"id":"C","text":"Acționează ca un antagonist al vitaminei K, blocând sinteza factorilor de coagulare."},{"id":"D","text":"Inhibă direct trombina pentru a preveni formarea cheagurilor."},{"id":"E","text":"Mediază adeziunea trombocitelor la peretele vascular lezat și stabilizează factorul procoagulant VIII."}],"correct":["E"],"pages":[571],"source":"set-2"},{"id":"set2-MZgt-NOh","fingerprint":"4316e652ed7d906c","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"În boala von Willebrand, ce caracterizează forma severă a afecțiunii în ceea ce privește deficitele de factori și riscul hemoragic?","options":[{"id":"A","text":"Un deficit grav de FvW asociat cu un deficit sever de factor VIII, având un risc hemoragic major."},{"id":"B","text":"Un consum rapid al factorilor de coagulare, fără un deficit specific de FvW sau factor VIII."},{"id":"C","text":"Un deficit izolat de factor VIII, cu niveluri normale ale FvW."},{"id":"D","text":"Un deficit de FvW ≤ 25% și niveluri normale sau scăzute de factor VIII, cu risc hemoragic moderat."},{"id":"E","text":"Prezența de anticorpi specifici anti-FvW, fără un deficit genetic al acestuia."}],"correct":["A"],"pages":[571],"source":"set-2"},{"id":"set2-FVdOFH_T","fingerprint":"5e859736a6b13ff4","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afecțiuni reprezintă indicații terapeutice pentru anticoagulantele orale?","options":[{"id":"A","text":"Tratamentul curativ al tromboflebitelor profunde ale membrelor."},{"id":"B","text":"Sindromul antifosfolipidic."},{"id":"C","text":"Tratamentul bolii hemoragice a nou-născutului."},{"id":"D","text":"Profilaxia primară a emboliei sistemice în cazul fibrilației atriale."},{"id":"E","text":"Profilaxia antitrombotică a protezelor valvulare metalice."}],"correct":["A","B","D","E"],"pages":[571],"source":"set-2"},{"id":"set2-Xs_Cy3FX","fingerprint":"1686d9b3e2baf829","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce medicament face parte din clasa noilor anticoagulante orale (NACO) și acționează ca un inhibitor direct de trombină?","options":[{"id":"A","text":"Rivaroxabanul (Xarelto)."},{"id":"B","text":"Apixabanul (Eliquis)."},{"id":"C","text":"Acenocumarolul (Sintrom)."},{"id":"D","text":"Dabigatranul (Pradaxa)."},{"id":"E","text":"Edoxaban (Lixiana)."}],"correct":["D"],"pages":[571],"source":"set-2"},{"id":"set2-kWlzKLQf","fingerprint":"6369fc3f14db6648","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Pentru un pacient aflat sub tratament cu acenocumarol, care este valoarea țintă recomandată a INR pentru a permite efectuarea unei extracții dentare programate cu risc redus de hemoragie?","options":[{"id":"A","text":"2-3"},{"id":"B","text":"&gt;3"},{"id":"C","text":"Exact 1,0"},{"id":"D","text":"Nu este necesară monitorizarea INR."},{"id":"E","text":"≤1,5"}],"correct":["E"],"pages":[571],"source":"set-2"},{"id":"set2-evnUQbCZ","fingerprint":"8a7888b3104c2f3e","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce presupune managementul post-extracțional al unui pacient tratat cronic cu anticoagulante orale clasice (ACO)?","options":[{"id":"A","text":"Reluarea administrării ACO se face în noaptea zilei în care s-a efectuat extracția."},{"id":"B","text":"Pacientul trebuie monitorizat timp de 48-72 de ore după reluarea ACO, până când INR atinge valoarea terapeutică optimă."},{"id":"C","text":"Se administrează heparină nefracționată în perfuzie timp de 3 zile după extracție."},{"id":"D","text":"Întreruperea tratamentului anticoagulant oral poate fi decisă de medicul stomatolog."},{"id":"E","text":"Se așteaptă 3 zile înainte de a relua tratamentul cu ACO pentru a nu influența coagularea locală."}],"correct":["A","B"],"pages":[571],"source":"set-2"},{"id":"set2-RjVYmBfe","fingerprint":"80e22ee3094deb3d","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce particularitate prezintă managementul perioperator al pacienților cu proteze valvulare metalice aflați sub tratament cu anticoagulante orale clasice (ACO) care necesită o extracție dentară?","options":[{"id":"A","text":"Se administrează antibiotice cu spectru larg pentru a reduce efectul ACO."},{"id":"B","text":"Se realizează extracția sub un INR terapeutic (2-3) datorită riscului trombotic."},{"id":"C","text":"Se trece permanent pe un nou anticoagulant oral (NACO) înainte de intervenție."},{"id":"D","text":"Este necesară substituția medicației ACO cu heparină (terapia \"punte\") până la atingerea unui INR ≤ 1,5."},{"id":"E","text":"Tratamentul cu ACO nu se întrerupe, din cauza riscului trombotic foarte mare."}],"correct":["D"],"pages":[571],"source":"set-2"},{"id":"set2-qUBfi746","fingerprint":"360b133a88abbcfb","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt caracteristicile heparinei cu greutate moleculară mică (fracționată) în comparație cu heparina nefracționată în contextul terapiei \"punte\"?","options":[{"id":"A","text":"Se administrează în injecții subcutanate la interval de 12/24 de ore."},{"id":"B","text":"Administrarea se întrerupe cu 6 ore înaintea unei extracții dentare."},{"id":"C","text":"Necesită monitorizare periodică a coagulogramei prin APTT."},{"id":"D","text":"Se administrează în regim de perfuzie intravenoasă continuă."},{"id":"E","text":"Prezintă un efect anticoagulant mai stabil."}],"correct":["A","E"],"pages":[572],"source":"set-2"},{"id":"set2-_Di-VQzl","fingerprint":"1ade094f121cbeaa","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Conform protocoalelor terapeutice, cu cât timp înainte de o extracție dentară se recomandă întreruperea administrării heparinei?","options":[{"id":"A","text":"Cu 6 ore înainte pentru heparina fracționată și cu 12 ore pentru cea nefracționată."},{"id":"B","text":"Imediat după realizarea hemostazei postextracționale."},{"id":"C","text":"Cu 12 ore înainte pentru heparina fracționată și cu 6 ore pentru cea nefracționată."},{"id":"D","text":"Cu 24 de ore înainte, indiferent de tipul de heparină."},{"id":"E","text":"Cu 48-72 de ore înainte, pentru a permite normalizarea INR-ului."}],"correct":["C"],"pages":[572],"source":"set-2"},{"id":"set2-g4i2ky0L","fingerprint":"1edb50fdb1b5a234","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt pașii corecți în managementul perioperator al unui pacient sub tratament cu anticoagulante orale clasice (ACO) care necesită terapie \"punte\"?","options":[{"id":"A","text":"Se temporizează reluarea heparinei până la 24 de ore postextracțional dacă persistă sângerarea."},{"id":"B","text":"Se reinițiază administrarea de ACO în noaptea aceleiași zile."},{"id":"C","text":"Se administrează concomitent heparina și ACO pentru 48-72 de ore."},{"id":"D","text":"Se reia administrarea de heparină la 6 ore postextracțional dacă s-a obținut hemostază eficientă."},{"id":"E","text":"Se oprește administrarea de heparină imediat ce se reintroduce tratamentul cu ACO."}],"correct":["B","C","D"],"pages":[572],"source":"set-2"},{"id":"set2-6DuI1xBV","fingerprint":"b077d8f5bda3c2e1","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce afirmații descriu corect managementul pacienților sub tratament cu noile anticoagulante orale (NACO) în vederea unei extracții dentare?","options":[{"id":"A","text":"Reluarea administrării se face la minimum 24 de ore postextracțional."},{"id":"B","text":"Antagonizarea efectului se poate face eficient cu vitamina K."},{"id":"C","text":"Efectul tuturor NACO-urilor poate fi evaluat prin teste comerciale disponibile."},{"id":"D","text":"Administrarea antitromboticului se întrerupe cu 1-3 zile înainte de extracție."},{"id":"E","text":"Este necesară terapia de substituție cu heparină."}],"correct":["A","D"],"pages":[572],"source":"set-2"},{"id":"set2-yW5P-wvn","fingerprint":"2519168aa62780ce","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"În cazul unei hemoragii postextracționale tardive la un pacient sub terapie anticoagulantă orală clasică, fără o cauză locală evidentă, care este o măsură terapeutică adecvată?","options":[{"id":"A","text":"Creșterea dozei de anticoagulant oral pentru a stabiliza INR-ul."},{"id":"B","text":"Administrarea de heparină în doze terapeutice."},{"id":"C","text":"Administrarea intramusculară a unei doze de 10-20 mg de fitomenadionă (vitamina K)."},{"id":"D","text":"Administrarea de acid acetilsalicilic pentru a contracara efectul."},{"id":"E","text":"Utilizarea de plasmă proaspătă congelată"}],"correct":["C","E"],"pages":[572],"source":"set-2"},{"id":"set2-SdUttifa","fingerprint":"1a4aeef1838911b6","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele medicamente sunt clasificate ca inhibitori ai receptorilor P2Y12?","options":[{"id":"A","text":"Acidul acetilsalicilic"},{"id":"B","text":"Abciximab"},{"id":"C","text":"Clopidogrel"},{"id":"D","text":"Indobufen"},{"id":"E","text":"Ticagrelor"}],"correct":["C","E"],"pages":[572],"source":"set-2"},{"id":"set2-Q0J8ZS4B","fingerprint":"39e62c22d0cd58e4","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele situații clinice reprezintă indicații terapeutice pentru medicamentele antiagregante plachetare?","options":[{"id":"A","text":"Tratamentul hemoragiilor postextracționale la pacienții anticoagulați."},{"id":"B","text":"Profilaxia recurenței accidentelor ischemice tranzitorii (AIT)."},{"id":"C","text":"Terapia de substituție înaintea unei extracții dentare."},{"id":"D","text":"Fibrilația atrială, în cazul în care anticoagulantele orale sunt contraindicate."},{"id":"E","text":"Angioplastie coronariană percutană post-infarct miocardic acut."}],"correct":["B","D","E"],"pages":[572],"source":"set-2"},{"id":"set2-_7_lUY9A","fingerprint":"c7c54faebcb7cf99","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"În ce condiții este considerat ridicat riscul de complicații trombo-embolice la un pacient?","options":[{"id":"A","text":"Pacientul are antecedente de hipertensiune arterială și diabet zaharat."},{"id":"B","text":"Pacientul urmează tratament curativ pentru hipertensiune pulmonară primitivă."},{"id":"C","text":"Pacientul are o fracție de ejecție a ventriculului stâng de 40%."},{"id":"D","text":"Vârsta pacientului este de 60 de ani, fără alte comorbidități."},{"id":"E","text":"Pacientul prezintă fibrilație atrială asociată cu valvulopatii."}],"correct":["A","E"],"pages":[572],"source":"set-2"},{"id":"set2-i_7Jj-gx","fingerprint":"9cbb1fd0c260c0b4","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele condiții sunt considerate a avea un risc ridicat de complicații trombo-embolice?","options":[{"id":"A","text":"Angioplastie coronariană percutană cu stent efectuată în urmă cu 6 luni."},{"id":"B","text":"Fibrilație atrială asociată cu valvulopatii."},{"id":"C","text":"Proteze valvulare mecanice în poziție mitrală."},{"id":"D","text":"Insuficiență cardiacă congestivă cu o fracție de ejecție a ventriculului stâng de 40%."},{"id":"E","text":"Vârsta de 70 de ani fără istoric de HTA sau diabet zaharat."}],"correct":["A","B","C"],"pages":[573],"source":"set-2"},{"id":"set2-wxr8YPoE","fingerprint":"6223e563aab97fca","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce perioadă de întrerupere a tratamentului este recomandată pentru un pacient care ia clopidogrel și are un risc de trombembolie redus, dar un risc de hemoragie postextracțională semnificativ?","options":[{"id":"A","text":"1 zi"},{"id":"B","text":"3-5 zile"},{"id":"C","text":"5 zile"},{"id":"D","text":"Tratamentul nu se întrerupe."},{"id":"E","text":"7 zile"}],"correct":["C"],"pages":[573],"source":"set-2"},{"id":"set2-lsB97vzH","fingerprint":"09ee5be818189c27","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"În ce condiții se pot efectua extracții dentare la un pacient cu risc tromboembolic ridicat care nu poate întrerupe administrarea inhibitorilor P2Y₁₂?","options":[{"id":"A","text":"După administrarea de vitamină K pentru a contracara efectul."},{"id":"B","text":"Doar în situații de urgență și în condiții de spitalizare."},{"id":"C","text":"Dacă se reduce doza de inhibitor P2Y₁₂ cu 24 de ore înainte."},{"id":"D","text":"Oricând, dacă se utilizează măsuri hemostatice locale."},{"id":"E","text":"Dacă riscul de hemoragie postextracțională este estimat ca fiind redus."}],"correct":["B"],"pages":[573],"source":"set-2"},{"id":"set2-Uqpt0byt","fingerprint":"59f8e905a7c58248","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Un pacient diabetic, asimptomatic, cu regim stabil și o valoare a glicemiei a jeun de 130 mg/dl și HbA1c de 5.8% se încadrează în ce categorie de risc pentru extracția dentară?","options":[{"id":"A","text":"Risc crescut"},{"id":"B","text":"Risc neevaluabil"},{"id":"C","text":"Risc moderat"},{"id":"D","text":"Risc scăzut"},{"id":"E","text":"Risc foarte crescut"}],"correct":["D"],"pages":[573],"source":"set-2"},{"id":"set2-r8Rt00fl","fingerprint":"e242ca3adae308eb","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt abordările anestezice recomandate pentru un pacient diabetic cu risc moderat?","options":[{"id":"A","text":"Anestezie tronculară periferică cu vasoconstrictor."},{"id":"B","text":"Anestezie plexală cu vasoconstrictor 1:200.000."},{"id":"C","text":"Temporizarea intervenției până când glicemia scade sub 180 mg/dl."},{"id":"D","text":"Anestezie tronculară periferică fără vasoconstrictor asociat."},{"id":"E","text":"Anestezie plexală cu soluții ce conțin vasoconstrictor."}],"correct":["D","E"],"pages":[573],"source":"set-2"},{"id":"set2-kvAyj9g4","fingerprint":"7a1cac5b0385bfde","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce măsuri specifice sunt indicate în managementul postextracțional la pacienții cu leucemii cronice?","options":[{"id":"A","text":"Administrarea de inhibitori ai receptorilor P2Y₁₂."},{"id":"B","text":"Monitorizarea fracției de ejecție a ventriculului stâng."},{"id":"C","text":"Verificarea nivelului de HbA1c."},{"id":"D","text":"Antibioprofilaxia infecțiilor locale."},{"id":"E","text":"Sutura plăgii pentru hemostază locală."}],"correct":["D","E"],"pages":[573],"source":"set-2"},{"id":"set2-T_rMwXqj","fingerprint":"6c1510d0ab23b653","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce mecanism principal stă la baza modificărilor de hemostază la pacienții cu tulburări hepatice?","options":[{"id":"A","text":"Apariția de episoade frecvente de cetoacidoză."},{"id":"B","text":"Inhibarea receptorilor P2Y₁₂ de la nivelul trombocitelor."},{"id":"C","text":"Apărare prin tulburarea sintezei lipidice"},{"id":"D","text":"Vasculopatia periferică ce crește riscul de hemoragie."},{"id":"E","text":"Perturbarea sintezei factorilor de coagulare precum protrombina și fibrinogenul."}],"correct":["E"],"pages":[573],"source":"set-2"},{"id":"set2-PQjYnwP5","fingerprint":"bfefaa56f02bd6f7","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este pragul glicemic general sub care se recomandă efectuarea extracțiilor dentare la pacienții diabetici?","options":[{"id":"A","text":"180 mg/dl"},{"id":"B","text":"220 mg/dl"},{"id":"C","text":"160 mg/dl"},{"id":"D","text":"200 mg/dl"},{"id":"E","text":"140 mg/dl"}],"correct":["A"],"pages":[573],"source":"set-2"},{"id":"set2-ZrhXcKnK","fingerprint":"6e414e53c38a8be6","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt factorii menționați ce pot contribui la apariția osteonecrozei postextracționale la pacienții infectați cu HIV?","options":[{"id":"A","text":"Rolul inhibitor asupra osteoclastogenezei exercitat de medicamentul Ritonavir."},{"id":"B","text":"Apariția infecțiilor oportuniste sistemice cauzate de imunosupresie."},{"id":"C","text":"Terapia cu inhibitori ai calcineurinei, precum ciclosporina."},{"id":"D","text":"Fibroza peretelui vascular la nivelul microvascularizației osoase."},{"id":"E","text":"Utilizarea corticosteroizilor în tratamentul afecțiunilor asociate infecției HIV."}],"correct":["A","E"],"pages":[574],"source":"set-2"},{"id":"set2-V1rZcBAm","fingerprint":"16a3752e30e46b73","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Un pacient cu boala Crohn, sub tratament de cinci luni cu prednison, necesită o extracție dentară. Care sunt elementele esențiale ale conduitei postextracționale în acest caz?","options":[{"id":"A","text":"Realizarea extracției cu lambou care să acopere complet osul alveolar."},{"id":"B","text":"Administrarea de agenți biologici, precum rituximab."},{"id":"C","text":"Antibioterapie și o igienă locală riguroasă."},{"id":"D","text":"Așteptarea a 18-21 de zile postextracțional înainte de a continua tratamentul."},{"id":"E","text":"Creșterea dozei de corticosteroid postoperator pentru a controla inflamația."}],"correct":["C"],"pages":[574],"source":"set-2"},{"id":"set2-B0t5NAmw","fingerprint":"237de04f207f50e2","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este principalul risc intraoperator la un pacient sub corticoterapie de lungă durată care este supus unei extracții dentare și ce măsură preventivă se poate adopta?","options":[{"id":"A","text":"Apariția osteoradionecrozei; se administrează antibiotice cu spectru larg."},{"id":"B","text":"Inhibarea osteoclastogenezei; se întrerupe temporar tratamentul cu corticosteroizi."},{"id":"C","text":"Scăderea importantă a tensiunii arteriale din cauza răspunsului inadecvat la stres; se poate crește doza de corticosteroid preoperator."},{"id":"D","text":"Hemoragie necontrolată; se administrează vitamina K preoperator."},{"id":"E","text":"Rejetul alogen; se administrează inhibitori mTOR precum sirolimus."}],"correct":["C"],"pages":[574],"source":"set-2"},{"id":"set2-4FSFPptv","fingerprint":"08b454f35bec2ec5","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este intervalul de timp optim pentru realizarea extracțiilor dentare la dinții cu risc, în vederea prevenirii osteoradionecrozei la un pacient programat pentru radioterapie în sfera oro-maxilo-facială?","options":[{"id":"A","text":"În timpul ședințelor de radioterapie, pentru a beneficia de efectul tumoricid."},{"id":"B","text":"În primele 12 luni de la instituirea radioterapiei."},{"id":"C","text":"Cu 18-21 de zile înainte de începerea radioterapiei."},{"id":"D","text":"Imediat după terminarea radioterapiei."},{"id":"E","text":"În primele 3 luni de la terminarea radioterapiei."}],"correct":["C"],"pages":[574],"source":"set-2"},{"id":"set2-UArm9nPw","fingerprint":"aca5b367fed9813a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce modificări la nivel tisular justifică riscul crescut de osteoradionecroză după o extracție dentară la un pacient iradiat la nivelul extremității cefalice?","options":[{"id":"A","text":"Apariția infecțiilor oportuniste sistemice."},{"id":"B","text":"Modificări structurale ale microvascularizației osoase, precum fibroza peretelui vascular."},{"id":"C","text":"Inhibarea osteoclastogenezei de către doza de radiații."},{"id":"D","text":"O producție insuficientă de cortizol de către glandele suprarenale."},{"id":"E","text":"Un risc latent de apoptoză în momentul diviziunii osteoblastelor."}],"correct":["B","E"],"pages":[574],"source":"set-2"},{"id":"set2-PbJF4RSX","fingerprint":"24e14bda3ec69552","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele medicamente fac parte din clasa inhibitorilor de calcineurină sau a inhibitorilor IMDH?","options":[{"id":"A","text":"Sirolimus"},{"id":"B","text":"Rituximab"},{"id":"C","text":"Tacrolimus"},{"id":"D","text":"Azatioprină"},{"id":"E","text":"Ciclosporină"}],"correct":["C","D","E"],"pages":[574],"source":"set-2"},{"id":"set2-12kqXwYo","fingerprint":"8cc6dac323a97490","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afirmații despre corticoterapie sunt adevărate?","options":[{"id":"A","text":"Un tratament este considerat de lungă durată dacă depășește trei luni."},{"id":"B","text":"Dexametazona este un corticosteroid cu durată scurtă de acțiune."},{"id":"C","text":"Indicațiile terapeutice includ psoriazisul și boala Crohn."},{"id":"D","text":"Principalul mecanism de acțiune este inhibarea mTOR."},{"id":"E","text":"Prednisonul și metilprednisolonul sunt corticosteroizi cu durată scurtă de acțiune."}],"correct":["A","C","E"],"pages":[574],"source":"set-2"},{"id":"set2-hwsJJF1w","fingerprint":"b266b8227d071cf1","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care sunt valorile minime ale leucocitelor și trombocitelor care permit efectuarea unei extracții dentare de necesitate la un pacient care a urmat un tratament chimioterapic?","options":[{"id":"A","text":"Leucocite &gt; 20000/µL și trombocite &gt; 500000/µL"},{"id":"B","text":"Leucocite &gt; 20000/µL și trombocite &gt; 50000/µL"},{"id":"C","text":"Leucocite &gt; 50000/µL și trombocite &gt; 2000/µL"},{"id":"D","text":"Leucocite &gt; 2000/µL și trombocite &gt; 50000/µL"},{"id":"E","text":"Leucocite &gt; 5000/µL și trombocite &gt; 150000/µL"}],"correct":["D"],"pages":[575],"source":"set-2"},{"id":"set2-1Md7jElX","fingerprint":"cf8abe3aee55366c","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este intervalul de timp mediu în care poate surveni osteonecroza maxilarelor la pacienții sub tratament cu bifosfonați administrați pe cale intravenoasă?","options":[{"id":"A","text":"După aproximativ 36 de luni de tratament"},{"id":"B","text":"După 3-6 luni de tratament"},{"id":"C","text":"Riscul este inexistent pentru calea intravenoasă"},{"id":"D","text":"După mai mult de 10 ani de la inițierea tratamentului"},{"id":"E","text":"În primele 4 săptămâni de tratament"}],"correct":["B"],"pages":[575],"source":"set-2"},{"id":"set2-_2U0cjOn","fingerprint":"78fdde085a2f6d8b","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt recomandările specifice pentru realizarea extracțiilor dentare de necesitate la un pacient aflat sub tratament cronic cu bifosfonați?","options":[{"id":"A","text":"Întreruperea tratamentului cu bifosfonați cu 6 luni înaintea intervenției chirurgicale."},{"id":"B","text":"Administrarea unei antibioterapii cu spectru larg pentru o perioadă de cel puțin 7-10 zile."},{"id":"C","text":"Realizarea manoperelor cât mai atraumatic posibil."},{"id":"D","text":"Înlocuirea temporară a bifosfonaților cu denosumab."},{"id":"E","text":"Evitarea utilizării antibioticelor pentru a nu masca o eventuală infecție osoasă incipientă."}],"correct":["B","C"],"pages":[575],"source":"set-2"},{"id":"set2-Cm8YHvmz","fingerprint":"5df14f20863d6a8b","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Prin ce se diferențiază denosumab-ul de bifosfonați în ceea ce privește riscurile și mecanismul de acțiune asupra țesutului osos?","options":[{"id":"A","text":"Denosumab-ul este un inhibitor de osteoclaste cu structură chimică de tip bifosfonat."},{"id":"B","text":"Denosumab-ul este indicat exclusiv în tratamentul bolii Paget."},{"id":"C","text":"Riscul de osteonecroză asociat cu denosumab este mai redus comparativ cu cel observat în cazul bifosfonaților."},{"id":"D","text":"Denosumab-ul are un timp de înjumătățire de peste 10 ani, similar bifosfonaților."},{"id":"E","text":"Efectul denosumab-ului asupra țesutului osos este reversibil, dispărând practic în totalitate după 6 luni de la administrare."}],"correct":["C","E"],"pages":[575],"source":"set-2"},{"id":"set2-HzKkbsRG","fingerprint":"5271ddec8e1aadbf","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce consecințe poate avea expunerea la agenți teratogeni și fetotoxici în perioada de organogeneză (începând cu săptămâna a 9-a de sarcină)?","options":[{"id":"A","text":"Întârzierea creșterii fătului."},{"id":"B","text":"Decesul fătului."},{"id":"C","text":"Riscul este limitat exclusiv la naștere prematură."},{"id":"D","text":"Apariția de anomalii structurale majore la nivelul organelor."},{"id":"E","text":"Anomalii la nivelul sistemului nervos central."}],"correct":["A","B","E"],"pages":[575],"source":"set-2"},{"id":"set2-UnAzzmfB","fingerprint":"89cfbe6a935d6323","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele medicamente sau clase de medicamente au fost asociate cu apariția osteonecrozei maxilarelor?","options":[{"id":"A","text":"Inhibitorii de osteoclaste de tip bifosfonați (ex: zoledronat)."},{"id":"B","text":"Anticorpii monoclonali anti-RANKL (ex: denosumab)."},{"id":"C","text":"Anticorpii monoclonali cu efect antiangiogenic (ex: bevacizumab)."},{"id":"D","text":"Agenții chimioterapici care determină supresie medulară."},{"id":"E","text":"Medicamentele utilizate exclusiv pentru osteogeneza imperfectă."}],"correct":["A","B","C"],"pages":[575],"source":"set-2"},{"id":"set2-Eirms-h3","fingerprint":"6f207c7b7dd47082","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt afirmațiile corecte cu privire la modificările și riscurile specifice fiecărui trimestru de sarcină?","options":[{"id":"A","text":"Majoritatea urgențelor dento-parodontale se manifestă în trimestrul al III-lea al sarcinii."},{"id":"B","text":"Trimestrul al II-lea este caracterizat printr-o solicitare maximă a organismului matern și deteriorarea progresivă a stării generale."},{"id":"C","text":"În trimestrul I, pot apărea sincope determinate de hipooxigenare cerebrală indusă de hormonii de sarcină."},{"id":"D","text":"Disgravidia, manifestată prin deshidratare severă și hipotensiune, este o complicație frecventă a trimestrului al II-lea."},{"id":"E","text":"Sindromul de compresie a venei cave inferioare reprezintă un risc în trimestrul al III-lea, în special în poziție de decubit dorsal."}],"correct":["A","C","E"],"pages":[576],"source":"set-2"},{"id":"set2-wXOUCtnC","fingerprint":"40b07342261baec3","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce măsuri specifice trebuie luate la programarea unei gravide în primul trimestru, care prezintă tendință la vomă, pentru o intervenție de urgență?","options":[{"id":"A","text":"Pacienta va fi tratată în poziție șezândă și programată în cursul zilei, nu dimineața."},{"id":"B","text":"Programarea se face dimineața pentru a evita interferența cu mesele principale."},{"id":"C","text":"Orice intervenție, inclusiv urgențele, trebuie amânată până în al doilea trimestru."},{"id":"D","text":"Se recomandă programarea imediat după o masă principală pentru a stabiliza nivelul glicemiei."},{"id":"E","text":"Intervenția se realizează în decubit dorsal pentru a asigura o bună oxigenare cerebrală."}],"correct":["A"],"pages":[576],"source":"set-2"},{"id":"set2-qVaG47oW","fingerprint":"98d444dc6950fb3f","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt consecințele potențiale ale sumării efectelor catecolaminelor endogene (eliberate din cauza stresului și durerii) și a celor exogene (din vasoconstrictorii anestezici) la o pacientă gravidă?","options":[{"id":"A","text":"Ameliorarea circulației placentare și un efect tocolitic."},{"id":"B","text":"Hipoxie și tahicardie reflexă a fătului."},{"id":"C","text":"O creștere a stabilității musculaturii uterine."},{"id":"D","text":"Diminuarea marcată a circulației feto-placentare."},{"id":"E","text":"Declanșarea precoce a travaliului."}],"correct":["B","D","E"],"pages":[576],"source":"set-2"},{"id":"set2-rA5OpOD4","fingerprint":"89d19f946f57b653","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este afirmația corectă referitoare la farmacocinetica medicamentelor în timpul sarcinii?","options":[{"id":"A","text":"Utilizarea medicamentelor este recomandată în special în primul trimestru datorită adaptărilor farmacocinetice."},{"id":"B","text":"Concentrația plasmatică maximă a medicamentelor crește, iar viteza de eliminare scade."},{"id":"C","text":"Există un volum mic de distribuție a medicamentului și o scădere a solubilității lipidice."},{"id":"D","text":"Dinamica specifică sarcinii, incluzând volumul mare de distribuție și solubilitatea lipidică crescută, contribuie la un acces facil al medicamentelor prin placentă."},{"id":"E","text":"În sarcină, timpul de înjumătățire plasmatică al medicamentelor este mai lung, ceea ce reduce pasajul transplacentar."}],"correct":["D"],"pages":[576],"source":"set-2"},{"id":"set2-7WwOOtwv","fingerprint":"9a3e4dfb4351cfec","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Pe baza criteriului de legare de proteinele plasmatice, care este raționamentul pentru alegerea anestezicelor locale la gravide?","options":[{"id":"A","text":"O rată mică de legare de proteinele plasmatice asigură un efect anestezic mai rapid și mai sigur pentru făt."},{"id":"B","text":"Se preferă substanțele cu rată mare de legare, deoarece fracțiunea liberă, capabilă să traverseze placenta, este redusă."},{"id":"C","text":"Prilocaina este preferată articainei datorită unei legări superioare de proteinele plasmatice."},{"id":"D","text":"Xilina și mepivacaina sunt indicate la gravide, având o proporție de 30% care circulă liber."},{"id":"E","text":"Articaina este recomandată deoarece se leagă în proporție de 90% de proteinele plasmatice."}],"correct":["B","E"],"pages":[576],"source":"set-2"},{"id":"set2-ZdfQUgaB","fingerprint":"8e34ae3d86be8a61","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Conform clasificării FDA bazată pe potențialul teratogen, care dintre următoarele substanțe utilizate în anestezia locală sunt încadrate în clasa C?","options":[{"id":"A","text":"Mepivacaina"},{"id":"B","text":"Articaina"},{"id":"C","text":"Lidocaina"},{"id":"D","text":"Adrenalina"},{"id":"E","text":"Prilocaina"}],"correct":["D","E"],"pages":[576],"source":"set-2"},{"id":"set2-RIGVwEI1","fingerprint":"67d90184203dd549","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt condițiile specifice de utilizare a adrenalinei ca vasoconstrictor în anestezia locală la pacientele gravide?","options":[{"id":"A","text":"Utilizarea sa corectă are un efect tocolitic asupra musculaturii uterine."},{"id":"B","text":"Este contraindicată complet deoarece face parte din clasa C a FDA."},{"id":"C","text":"Poate fi folosită doar în diluții de maximum 1:200 000."},{"id":"D","text":"În diluții de 1:200 000, adrenalina ameliorează circulația placentară."},{"id":"E","text":"Se recomandă diluții mai concentrate, de exemplu 1:100 000, pentru a reduce sângerarea."}],"correct":["A","C","D"],"pages":[576],"source":"set-2"},{"id":"set2-zIJ_CdD-","fingerprint":"5d7e855fd77a392d","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este considerat cel mai sigur medicament analgezic și antipiretic pentru femeile însărcinate, deși utilizarea sa necesită precauție?","options":[{"id":"A","text":"Acid clavulanic"},{"id":"B","text":"Amoxicilină"},{"id":"C","text":"Clindamicină"},{"id":"D","text":"Cefalosporină"},{"id":"E","text":"Acetaminofen"}],"correct":["E"],"pages":[577],"source":"set-2"},{"id":"set2-vzgc3ww9","fingerprint":"6f9b9b7290f6a0da","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce riscuri potențiale sunt asociate cu utilizarea acetaminofenului în timpul sarcinii?","options":[{"id":"A","text":"Mutații, retard mental și anomalii oculare."},{"id":"B","text":"Convulsii la nou-născut în perioada de lactație."},{"id":"C","text":"Hipotensiune, tahicardie și șoc la mamă."},{"id":"D","text":"Reacții alergice la β-lactamine."},{"id":"E","text":"ADHD, tulburări de spectru autist (ASD) și astm."}],"correct":["E"],"pages":[577],"source":"set-2"},{"id":"set2-22WobX_W","fingerprint":"5d1ba4f49137596e","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afirmații despre utilizarea antibioticelor în sarcină sunt adevărate?","options":[{"id":"A","text":"Cefalosporinele sunt contraindicate în sarcină din cauza efectelor teratogene."},{"id":"B","text":"Asocierea amoxicilină - acid clavulanic este complet sigură atât în sarcină, cât și în lactație."},{"id":"C","text":"Lincomicinele, precum clindamicina, reprezintă o alternativă pentru pacientele alergice la β-lactamine."},{"id":"D","text":"Aproape toate antibioticele traversează bariera placentară."},{"id":"E","text":"Penicilinele (clasa B) pot fi folosite, cu excepția cazului în care mama este alergică."}],"correct":["C","D","E"],"pages":[577],"source":"set-2"},{"id":"set2-O1qop2q3","fingerprint":"805e9bc68ae64476","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce efect advers specific poate avea administrarea combinației amoxicilină - acid clavulanic în perioada de lactație asupra nou-născutului?","options":[{"id":"A","text":"Convulsii"},{"id":"B","text":"Astm"},{"id":"C","text":"Tulburări de spectru autist (ASD)"},{"id":"D","text":"Anomalii oculare"},{"id":"E","text":"Retard mental"}],"correct":["A"],"pages":[577],"source":"set-2"},{"id":"set2-duiXSeEi","fingerprint":"56cd936610c5e688","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afirmații referitoare la radiodiagnosticul stomatologic în sarcină sunt corecte?","options":[{"id":"A","text":"Radiografiile convenționale stomatologice sunt considerate complet sigure și pot fi efectuate de rutină, fără precauții speciale."},{"id":"B","text":"O radiografie retroalveolară expune fătul la o doză de 0,01 mrad."},{"id":"C","text":"Chiar dacă expunerea este minimă, se recomandă utilizarea măsurilor de protecție precum șorțul și gulerele tiroidiene."},{"id":"D","text":"Expunerea fătului la doze de radiații mai mari de 10 rad poate duce la mutații și anomalii oculare."},{"id":"E","text":"Doza de radiații la o radiografie retroalveolară este echivalentă cu 10 rad."}],"correct":["B","C","D"],"pages":[577],"source":"set-2"},{"id":"set2-EwNRecyJ","fingerprint":"8e3ec66f8fea5ce9","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce mecanism fiziopatologic stă la baza sindromului de compresie a venei cave inferioare la gravidă?","options":[{"id":"A","text":"Traversarea barierei placentare de către antibioticele din clasa penicilinelor."},{"id":"B","text":"O reacție alergică la β-lactamine, manifestată prin tahicardie și hipotensiune."},{"id":"C","text":"Poziționarea în decubit dorsal, care duce la compresia venei cave inferioare și a aortei de către uterul mărit."},{"id":"D","text":"Expunerea la doze mari de radiații în timpul unui examen radiologic."},{"id":"E","text":"Creșterea bruscă a debitului cardiac și a volumului vascular cerebral."}],"correct":["C"],"pages":[577],"source":"set-2"},{"id":"set2-MPLF_2Lz","fingerprint":"e4a25cfe641b1ba6","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt manifestările clinice caracteristice sindromului de compresie a venei cave inferioare?","options":[{"id":"A","text":"Scăderea coeficientului intelectual la făt."},{"id":"B","text":"Risc de șoc și hipoxie fetală în absența intervenției."},{"id":"C","text":"Apariția de mutații genetice și anomalii oculare."},{"id":"D","text":"Amețeală și senzație acută de lipsă de aer."},{"id":"E","text":"Hipotensiune și tahicardie."}],"correct":["B","D","E"],"pages":[577],"source":"set-2"},{"id":"set2-Hbmn4-4l","fingerprint":"141f12fd644cf51b","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este manevra terapeutică de urgență recomandată în cazul unei gravide care dezvoltă sindromul de compresie a venei cave inferioare?","options":[{"id":"A","text":"Plasarea pacientei în decubit lateral drept."},{"id":"B","text":"Plasarea pacientei în decubit lateral stâng."},{"id":"C","text":"Menținerea pacientei în decubit dorsal și ridicarea picioarelor."},{"id":"D","text":"Administrarea unui antibiotic din clasa cefalosporinelor."},{"id":"E","text":"Efectuarea unei radiografii pentru a evalua poziția fătului."}],"correct":["B"],"pages":[577],"source":"set-2"},{"id":"set2--KUZ-Rdi","fingerprint":"a90e8e1b69260d30","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele condiții constituie contraindicații absolute pentru efectuarea extracției dentare?","options":[{"id":"A","text":"Sinuzita maxilară rinogenă"},{"id":"B","text":"Infarctul miocardic survenit cu 3 luni în urmă"},{"id":"C","text":"Pericoronarita acută asociată unui molar de minte"},{"id":"D","text":"Leucemia acută"},{"id":"E","text":"Prezența dinților într-o masă tumorală cu caracter malign"}],"correct":["B","D"],"pages":[568],"source":"set-2"},{"id":"set2--rs0uWW1","fingerprint":"123239a154118593","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afecțiuni impun instituirea antibioprofilaxiei endocarditei infecțioase înaintea extracției dentare?","options":[{"id":"A","text":"Afecțiunile cardiace congenitale corectate chirurgical, fără șunt rezidual, la un an postoperator"},{"id":"B","text":"Hipertensiunea arterială esențială necomplicată"},{"id":"C","text":"Protezele valvulare de tip homograft"},{"id":"D","text":"Endocardita infecțioasă în antecedentele pacientului"},{"id":"E","text":"Afecțiunile cardiace congenitale cianogene netratate"}],"correct":["C","D","E"],"pages":[569],"source":"set-2"},{"id":"set2-Kb7u-D95","fingerprint":"aa992d9f68148bf9","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele sindroame și patologii sunt clasificate drept cauze de fragilitate capilară primară?","options":[{"id":"A","text":"Purpura cașectică"},{"id":"B","text":"Sindromul Ehlers-Danlos"},{"id":"C","text":"Osteogeneza imperfecta"},{"id":"D","text":"Boala Cushing"},{"id":"E","text":"Sindromul Marfan"}],"correct":["B","C","E"],"pages":[569],"source":"set-2"},{"id":"set2-foasRqp2","fingerprint":"642b02ca352e116b","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Prin ce mecanism patogenic determină coagularea intravasculară diseminată și disecția de aortă apariția purpurelor trombocitare?","options":[{"id":"A","text":"Prin repartiția anormală a trombocitelor"},{"id":"B","text":"Prin alterarea primară a funcționalității trombocitelor"},{"id":"C","text":"Prin producția scăzută de trombocite la nivel medular"},{"id":"D","text":"Prin consumul excesiv al trombocitelor"},{"id":"E","text":"Prin distrugerea în exces a trombocitelor de origine autoimună"}],"correct":["D"],"pages":[570],"source":"set-2"},{"id":"set2-XBudS-N1","fingerprint":"64039ad718169c14","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"În cadrul trombocitopatiilor post-medicamentoase, care dintre următoarele substanțe acționează prin interacțiunea directă cu fosfodiesterazele plachetare?","options":[{"id":"A","text":"Medicamentele citostatice"},{"id":"B","text":"Clorpromazina"},{"id":"C","text":"Aspirina"},{"id":"D","text":"Cafeina"},{"id":"E","text":"Aminofilina"}],"correct":["A","D","E"],"pages":[570],"source":"set-2"},{"id":"set2-1hc2Bx-X","fingerprint":"966fd3b74ffa01c1","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele variante terapeutice sunt adecvate în protocoalele de antibioprofilaxie a endocarditei infecțioase destinate unui pacient adult supus unei proceduri stomatologice invazive?","options":[{"id":"A","text":"Amoxicilină 2 g administrată per os cu o oră înaintea intervenției"},{"id":"B","text":"Amoxicilină 50 mg/kg administrată per os cu o oră înaintea intervenției"},{"id":"C","text":"Cefalosporine 2 g administrate intravenos cu o oră înainte de intervenție"},{"id":"D","text":"Ceftriaxonă 1 g administrată intravenos cu 30 de minute înainte de intervenție"},{"id":"E","text":"Cefazolină 1 g administrată intravenos cu 30 de minute înainte de intervenție"}],"correct":["A","D","E"],"pages":[569],"source":"set-2"},{"id":"set2-6SufKgGZ","fingerprint":"37874cd2382b5f71","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Afecțiunile virale pot fi implicate în dereglările hemostazei primare. Care dintre următoarele mecanisme descriu corect influența infecțiilor virale asupra riscului hemoragic?","options":[{"id":"A","text":"Producerea trombocitopatiilor secundare prin interacțiunea directă a componentelor virale cu fosfodiesterazele plachetare"},{"id":"B","text":"Producerea purpurelor trombocitare prin distrugerea în exces a trombocitelor, ca urmare a infecției cu virusul imunodeficienței umane, citomegalovirus, virusul rujeolic sau rubeolic"},{"id":"C","text":"Apariția purpurelor vasculare infecțioase în cazul infecției cu virusul gripal, rujeolic, rubeolic sau varicelo-zosterian"},{"id":"D","text":"Declanșarea purpurelor vasculare autoimune printr-un mecanism exclusiv mediat viral"},{"id":"E","text":"Generarea purpurelor trombocitare prin aloimunizare post-virală, determinând o producție scăzută de trombocite"}],"correct":["B","C"],"pages":[570],"source":"set-2"},{"id":"set2-aS0y_fyh","fingerprint":"c936ef4c77613779","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt asocierile veridice referitoare la severitatea clinică a hemoragiei și concentrația factorilor de coagulare la pacienții hemofilici?","options":[{"id":"A","text":"Hemofilia ușoară prezintă o concentrație a factorilor VIII/IX ≤ 25% și este dominată clinic de hemoragii spontane masive."},{"id":"B","text":"Hemofilia ușoară asociază o concentrație a factorilor VIII/IX ≤ 25% cu hemoragii provocate de traume majore sau post-intervenții chirurgicale."},{"id":"C","text":"Hemofilia severă presupune o concentrație a factorilor VIII/IX < 1%, manifestându-se prin hemoragii spontane."},{"id":"D","text":"Hemofilia severă este definită prin concentrații ale factorilor VIII/IX cuprinse între 5% și 25%."},{"id":"E","text":"Hemofilia moderată implică o concentrație a factorilor VIII/IX ≤ 5% și se caracterizează prin hemoragii provocate de traume minime."}],"correct":["B","C","E"],"pages":[570],"source":"set-2"},{"id":"set2-gF3BLNiB","fingerprint":"5db4a3b9c06ab21d","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele preparate terapeutice pot fi utilizate pentru substituția factorului deficitar la pacienții cu hemofilie B?","options":[{"id":"A","text":"Plasmă proaspătă/congelată"},{"id":"B","text":"Factor IX recombinant"},{"id":"C","text":"Concentrat de complex protrombinic"},{"id":"D","text":"Crioprecipitat congelat"},{"id":"E","text":"Sânge integral proaspăt"}],"correct":["A","B","C"],"pages":[570],"source":"set-2"},{"id":"set2-GC9RexQc","fingerprint":"23e54fd42c8da20e","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Ce factori etiologici și asocieri patologice determină coagulopatii secundare printr-un deficit de sinteză a factorilor dependenți de vitamina K?","options":[{"id":"A","text":"Administrarea de antibiotice cu spectru larg"},{"id":"B","text":"Deficitul ereditar de factor VII"},{"id":"C","text":"Sindroamele colestatice"},{"id":"D","text":"Coagularea intravasculară diseminată"},{"id":"E","text":"Boala hemoragică a nou-născutului"}],"correct":["A","C","E"],"pages":[571],"source":"set-2"},{"id":"set2-TnpCR-h3","fingerprint":"37ce0caf61fe3022","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt caracteristicile clinico-patogenice ale bolii von Willebrand?","options":[{"id":"A","text":"Forma ușoară/moderată a afecțiunii presupune un deficit de factor von Willebrand ≤ 25% și se asociază cu niveluri normale sau scăzute de factor VIII."},{"id":"B","text":"Factorul von Willebrand are rolul de a stabiliza factorul procoagulant VIII."},{"id":"C","text":"Forma severă este caracterizată printr-un deficit grav de factor von Willebrand care compensează și menține la un nivel normal factorul VIII."},{"id":"D","text":"Reprezintă o coagulopatie mixtă cauzată de deficitul genetic al unei glicoproteine cu rol în medierea adeziunii trombocitelor."},{"id":"E","text":"În forma ușoară/moderată riscul hemoragic este major, necesitând substituție perioperatorie obligatorie."}],"correct":["A","B","D"],"pages":[571],"source":"set-2"},{"id":"set2-PXs2uzD2","fingerprint":"784ff40d59f675b0","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt pașii terapeutici și recomandările specifice în managementul perioperator al pacientului hemofilic supus unei extracții dentare?","options":[{"id":"A","text":"Concentrația corespunzătoare de factor de coagulare deficitar se menține doar pe durata actului chirurgical."},{"id":"B","text":"Menținerea concentrațiilor adecvate de factor de coagulare deficitar este necesară până la vindecarea plăgii postextracționale, la 5-7 zile postoperator."},{"id":"C","text":"Instituirea terapiei de substituție perioperatorie este opțională, în funcție de severitatea sângerării intraoperatorii."},{"id":"D","text":"Realizarea intervenției chirurgicale este indicată în condiții de spitalizare."},{"id":"E","text":"Terapia de substituție trebuie să asigure atingerea nivelurilor adecvate de factor de coagulare conform indicațiilor medicului specialist hematolog."}],"correct":["B","D","E"],"pages":[570],"source":"set-2"},{"id":"set2-UsfEBeTK","fingerprint":"b2ce1a3b6dc0e6ac","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt afirmațiile corecte referitoare la managementul terapiei „punte” cu heparină la pacienții cu proteze valvulare metalice care necesită o extracție dentară?","options":[{"id":"A","text":"Administrarea heparinei fracționate se întrerupe cu 12 ore înaintea intervenției chirurgicale."},{"id":"B","text":"Reluarea administrării de heparină postextracțional se face invariabil la 24 de ore, indiferent de prezența sângerării locale."},{"id":"C","text":"Heparinele cu greutate moleculară mică prezintă un efect anticoagulant mai stabil, independent de valorile APTT."},{"id":"D","text":"Substituția medicației anticoagulante clasice orale se realizează exclusiv cu heparină nefracționată în perfuzie continuă."},{"id":"E","text":"Administrarea heparinei nefracționate se întrerupe cu 12 ore înaintea extracției dentare."}],"correct":["A","C"],"pages":[572],"source":"set-2"},{"id":"set2-zFV7nfIO","fingerprint":"2aa7459767191ace","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care dintre următoarele aspecte caracterizează conduita terapeutică specifică pacienților aflați sub tratament cu noile anticoagulante orale (NACO) în vederea realizării unei extracții dentare?","options":[{"id":"A","text":"Eficiența inhibitorilor de factor Xa se evaluează rutinier preoperator prin intermediul unor teste comerciale standardizate."},{"id":"B","text":"Reluarea administrării de NACO trebuie efectuată în noaptea aceleiași zile în care s-a practicat intervenția chirurgicală."},{"id":"C","text":"Acest tip de medicație impune obligatoriu terapia de substituție cu heparină pe durata întreruperii tratamentului de fond."},{"id":"D","text":"Hemoragiile postextracționale tardive la această categorie de pacienți beneficiază de antagonizare eficientă prin administrarea intramusculară de vitamină K."},{"id":"E","text":"Riscul hemoragic la pacienții tratați cu dabigatran se consideră prezent la o valoare a APTT ≥ 70 msec."}],"correct":["E"],"pages":[572],"source":"set-2"},{"id":"set2-ipelnmgR","fingerprint":"8fb749de8a87ad62","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Referitor la conduita terapeutică adoptată la pacienții aflați sub tratament cu inhibitori ai receptorilor P2Y₁₂, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Ticlopidina este încadrată din punct de vedere farmacologic în clasa blocanților receptorilor glicoproteici GPIIb/IIIa."},{"id":"B","text":"Ticagrelorul reprezintă un inhibitor ireversibil al receptorilor P2Y₁₂."},{"id":"C","text":"Tratamentul concomitent cu inhibitori COX-1 trebuie întrerupt în mod absolut dacă riscul de hemoragie postextracțională este semnificativ."},{"id":"D","text":"Medicația cu clopidogrel necesită o perioadă de întrerupere de 5 zile anterior extracției dentare, în caz de risc trombembolic redus."},{"id":"E","text":"Întreruperea administrării de prasugrel trebuie realizată cu 7 zile înaintea intervenției stomatologice programate."}],"correct":["D","E"],"pages":[573],"source":"set-2"},{"id":"set2-fzaybTcY","fingerprint":"018c36039f5998fb","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Ce conduită este adecvată în managementul pacienților aflați sub tratament cu anticoagulante clasice orale (antivitamine K) care se prezintă pentru o extracție dentară programată?","options":[{"id":"A","text":"Valoarea țintă a INR recomandată pentru a reduce riscul hemoragic înaintea unei extracții programate este ≤ 2,5."},{"id":"B","text":"Reluarea administrării anticoagulantelor clasice orale se va face în noaptea aceleiași zile în care s-a realizat extracția dentară."},{"id":"C","text":"Antagonizarea efectului anticoagulant prin administrare de fitomenadionă intramusculară se caracterizează printr-o eficiență imediată și crescută."},{"id":"D","text":"Monitorizarea pacientului post-reluare a tratamentului nu este indicată, cu excepția situațiilor de sângerare prelungită activă."},{"id":"E","text":"Efectul anticoagulant al acenocumarolului dispare rapid, menținându-se cel mult 12-24 de ore de la întreruperea dozelor."}],"correct":["B"],"pages":[571],"source":"set-2"},{"id":"set2-z_bNVveE","fingerprint":"7bdf2cb84591db1a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele condiții clinice definesc un risc ridicat de complicații tromboembolice la un pacient care urmează să suporte o extracție dentară?","options":[{"id":"A","text":"Antecedentele de sindrom coronarian acut."},{"id":"B","text":"Insuficiența cardiacă congestivă la care pacientul prezintă o fracție de ejecție a ventriculului stâng de 55%."},{"id":"C","text":"Prezența unei proteze valvulare mecanice situate în poziție mitrală."},{"id":"D","text":"Fibrilația atrială asociată cu un pacient având vârsta ≥ 75 de ani sau care are istoric de hipertensiune arterială."},{"id":"E","text":"Istoricul de angioplastie coronariană percutană cu montare de stent efectuată în urmă cu mai mult de 2 ani."}],"correct":["A","C","D"],"pages":[573],"source":"set-2"},{"id":"set2-5fboHfRt","fingerprint":"615a72a02062d752","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele caracteristici definesc pacienții cu diabet zaharat încadrați la risc moderat în vederea efectuării unei extracții dentare?","options":[{"id":"A","text":"Istoric recent de episoade frecvente de hipoglicemie și cetoacidoză."},{"id":"B","text":"Valoarea HbA1c cuprinsă între 6,2% și 7%."},{"id":"C","text":"Necesitatea ajustării frecvente a tratamentului antidiabetic."},{"id":"D","text":"Echilibru metabolic rezonabil cu prezența a puține dintre complicațiile bolii."},{"id":"E","text":"Glicemie a jeun sub 200 mg/dl."}],"correct":["B","D","E"],"pages":[573],"source":"set-2"},{"id":"set2-0D4CoNU6","fingerprint":"718f40da66380f0a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Referitor la particularitățile managementului extracției dentare la pacienții diagnosticați cu diabet zaharat, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"La pacienții cu risc crescut se intervine chirurgical în regim de urgență pentru a preveni dezechilibrele glicemice infecțioase."},{"id":"B","text":"La pacienții cu risc mediu este obligatorie folosirea vasoconstrictorului în tehnica anesteziei tronculare periferice."},{"id":"C","text":"Intervenția se recomandă a fi efectuată temporal la jumătatea intervalului dintre două mese."},{"id":"D","text":"La pacienții cu risc scăzut se poate utiliza anestezia plexală cu soluții anestezice cu vasoconstrictor în diluție de 1:200.000."},{"id":"E","text":"Extracțiile se pot efectua atunci când glicemia este relativ constantă și mai mică de 180 mg/dl."}],"correct":["C","D","E"],"pages":[573],"source":"set-2"},{"id":"set2--fxb2TbY","fingerprint":"090e718bc73f6f2e","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"În cazul pacienților diagnosticați cu leucemii cronice, care dintre următoarele entități patologice reprezintă complicații locale posibile în urma unei extracții dentare nesupravegheate corespunzător?","options":[{"id":"A","text":"Necroza osoasă."},{"id":"B","text":"Hiperplazia gingivală masivă."},{"id":"C","text":"Alveolita."},{"id":"D","text":"Gingivostomatita ulceronecrotică."},{"id":"E","text":"Formarea de chisturi maxilare gigante."}],"correct":["A","C","D"],"pages":[573],"source":"set-2"},{"id":"set2-BDGnadX9","fingerprint":"9823fa927a13834e","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Prin ce mecanisme tulburările hepatice influențează negativ procesul de hemostază și capacitatea de apărare a organismului în context chirurgical?","options":[{"id":"A","text":"Creșterea accelerată a numărului de trombocite circulante."},{"id":"B","text":"Perturbarea sintezei fibrinogenului."},{"id":"C","text":"Perturbarea sintezei protrombinei."},{"id":"D","text":"Tulburarea sintezei proteice."},{"id":"E","text":"Perturbarea sintezei vitaminei K."}],"correct":["B","C","D","E"],"pages":[573],"source":"set-2"},{"id":"set2-p0vcMEcm","fingerprint":"78da61729e5c9a2a","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este atitudinea terapeutică recomandată în cazul necesității unei extracții dentare la un pacient diabetic cu risc crescut?","options":[{"id":"A","text":"Efectuarea intervenției sub acoperire antibiotică profilactică de rutină dacă nivelul HbA1c depășește constant 7%, fără alte măsuri hemostatice locale."},{"id":"B","text":"Efectuarea imediată a intervenției exclusiv la jumătatea intervalului dintre două mese, pentru a evita instalarea cetoacidozei fulminante."},{"id":"C","text":"Utilizarea anesteziei plexale cu soluții cu vasoconstrictor 1:200.000 fără sutură postextracțională, pentru a permite drenajul sângerării."},{"id":"D","text":"Efectuarea anesteziei tronculare periferice exclusiv cu soluții anestezice cu vasoconstrictor asociat pentru minimizarea hemoragiei."},{"id":"E","text":"Temporizarea intervenției și colaborarea cu medicul nutriționist pentru obținerea unei glicemii sub 180 mg/dl, cu sutura plăgii și antibioterapie postextracțional."}],"correct":["E"],"pages":[573],"source":"set-2"},{"id":"set2-fwDy7GTn","fingerprint":"7485dfc2fc774ba3","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt afirmațiile adevărate privind managementul postextracțional și complicațiile asociate pacienților aflați sub tratament de lungă durată cu glucocorticoizi?","options":[{"id":"A","text":"Răspunsul la stres al organismului este redus, existând posibilitatea scăderii importante a tensiunii arteriale."},{"id":"B","text":"Durata tratamentului cu corticoizi este considerată de lungă durată dacă depășește șase luni."},{"id":"C","text":"Conduita postextracțională trebuie să cuprindă obligatoriu antibioterapie și o igienă locală riguroasă."},{"id":"D","text":"Insuficiența suprarenaliană indusă de corticoterapie dispare imediat după încetarea tratamentului."},{"id":"E","text":"Se impune scăderea dozei de corticosteroid preoperator pentru a preveni criza de insuficiență suprarenaliană."}],"correct":["A","C"],"pages":[573,574,575,576,577],"source":"set-2"},{"id":"set2-StA4rLM6","fingerprint":"2bfadce762ab5218","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele aspecte caracterizează conduita terapeutică referitoare la extracția dentară la pacienții supuși radioterapiei la nivelul extremității cefalice?","options":[{"id":"A","text":"Extracția dinților cu risc de patologie dento-parodontală se indică cu 18-21 zile înainte de începerea radioterapiei."},{"id":"B","text":"La 3 luni de la terminarea radioterapiei, structura osoasă revine la normal, permițând extracții fără risc de osteoradionecroză."},{"id":"C","text":"Radioterapia cu modularea intensității (IMRT) crește semnificativ riscul de osteoradionecroză comparativ cu metodele convenționale."},{"id":"D","text":"Radioterapia induce alterări ale microvascularizației osoase, inclusiv fibroza peretelui vascular."},{"id":"E","text":"Extracția de necesitate în primele 12 luni de la instituirea radioterapiei se realizează cu lambou care trebuie să acopere în întregime osul alveolar."}],"correct":["A","D","E"],"pages":[573,574,575,576,577],"source":"set-2"},{"id":"set2-i7bJy5Bj","fingerprint":"c6051ee67520137f","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care este afirmația adevărată privind managementul extracțiilor dentare la pacienții supuși tratamentului chimioterapic?","options":[{"id":"A","text":"Chimioterapia determină apariția supresiei medulare, afectând în principal seria roșie a sângelui."},{"id":"B","text":"Practicarea extracțiilor de necesitate este permisă doar când valorile leucocitelor depășesc 2000/µL, iar cele ale trombocitelor 50.000/µL."},{"id":"C","text":"Tulburările provocate de tratament se manifestă imediat, la câteva zile de la încetarea administrării medicației."},{"id":"D","text":"Riscul de supresie medulară face necesară amânarea oricărei intervenții chirurgicale cu minimum 3 luni de la ultima cură."},{"id":"E","text":"Administrarea medicației chimioterapice induce o hiperproducție a seriei albe, favorizând leucocitoza."}],"correct":["B"],"pages":[573,574,575,576,577],"source":"set-2"},{"id":"set2-WAcyg54P","fingerprint":"b7a3f5f50c82e5f4","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care sunt afirmațiile adevărate privind riscul de osteonecroză și managementul stomatologic al pacienților aflați sub tratament cronic cu medicație antiresorbtivă osoasă?","options":[{"id":"A","text":"În cazul bifosfonaților cu administrare orală, osteonecroza apare la aproximativ 3-6 luni de la inițierea tratamentului."},{"id":"B","text":"Efectul anticorpilor monoclonali anti-RANKL asupra țesutului osos este reversibil, dispărând practic în totalitate după 6 luni de la administrare."},{"id":"C","text":"Administrarea de antibioterapie cu spectru larg pentru minimum 7-10 zile este recomandată în cazul extracțiilor de necesitate la pacienții aflați sub terapie cu bifosfonați."},{"id":"D","text":"Anticorpii monoclonali cu efect antiangiogenic, precum bevacizumab, nu prezintă risc raportat de generare a osteonecrozei maxilarelor."},{"id":"E","text":"Se indică întreruperea tratamentului cu bifosfonați înaintea extracțiilor dentare, din cauza timpului de înjumătățire de peste 10 ani."}],"correct":["B","C"],"pages":[573,574,575,576,577],"source":"set-2"},{"id":"set2-4pU9PF_g","fingerprint":"6f0755b9c18ab0a5","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele asocieri referitoare la medicația specifică și efectele sale în contextul extracției dentare sunt adevărate?","options":[{"id":"A","text":"Azatioprina și leflunomida reprezintă agenți biologici cu risc scăzut de apariție a infecțiilor oportuniste."},{"id":"B","text":"Ciclosporina și tacrolimus reprezintă inhibitori ai calcineurinei utilizați în terapia cu imunosupresoare."},{"id":"C","text":"Sirolimus și everolimus sunt inhibitori mTOR care necesită antibioterapie postextracțională din cauza riscului de complicații infecțioase."},{"id":"D","text":"Corticosteroizii asociați terapiei afecțiunilor pacienților cu HIV reprezintă un factor de protecție împotriva apariției osteonecrozei."},{"id":"E","text":"Ritonavirul exercită un rol stimulator asupra osteoclastogenezei, prevenind osteonecroza postextracțională la pacienții cu infecție HIV."}],"correct":["B","C"],"pages":[573,574,575,576,577],"source":"set-2"},{"id":"set2-iXSfsTYR","fingerprint":"fb51e6e8ca9673aa","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Care dintre următoarele afirmații referitoare la utilizarea substanțelor anestezice și a vasoconstrictoarelor la pacientele gravide este adevărată?","options":[{"id":"A","text":"Articaina circulă liberă în proporție de 30%, nefiind indicată la gravide."},{"id":"B","text":"Felipresina ameliorează circulația placentară și se recomandă exclusiv în diluții de maximum 1:200.000."},{"id":"C","text":"Prilocaina face parte din clasa B a clasificării FDA privind riscul teratogen."},{"id":"D","text":"Adrenalina, utilizată ca și corectiv vasoconstrictor, prezintă un efect tocolitic asupra musculaturii uterine."},{"id":"E","text":"Lidocaina (xilina) și mepivacaina prezintă o rată de legare de proteinele plasmatice de 90%."}],"correct":["D"],"pages":[575,576,577],"source":"set-2"},{"id":"set2-YUaZWcnN","fingerprint":"b4e5a28a769eee38","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Expunerea produsului de concepție la agenți teratogeni și fetotoxici poate determina diverse complicații în funcție de perioada evolutivă. Care dintre următoarele consecințe sunt asociate expunerii în perioada de organogeneză (săptămâna 9 de sarcină - până la naștere)?","options":[{"id":"A","text":"Decesul fătului."},{"id":"B","text":"Apariția anomaliilor structurale la nivelul țesuturilor."},{"id":"C","text":"Mutații, retard mental și anomalii oculare la doze de radiații fetale sub 1 rad."},{"id":"D","text":"Anomalii la nivelul sistemului nervos central."},{"id":"E","text":"Întârzierea creșterii."}],"correct":["A","D","E"],"pages":[575,576,577],"source":"set-2"},{"id":"set2-QihynlMv","fingerprint":"54d6f6358d05873d","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Care dintre următoarele afirmații descriu proprietățile și profilul de siguranță al terapiei medicamentoase la gravide și în perioada de lactație?","options":[{"id":"A","text":"Aproape toate antibioticele traversează bariera placentară."},{"id":"B","text":"Lincomicinele pot fi utilizate ca alternativă pentru pacientele alergice la grupul β-lactaminelor."},{"id":"C","text":"În perioada de lactație, asocierea amoxicilină - acid clavulanic este lipsită de riscuri pentru nou-născut."},{"id":"D","text":"Acetaminofenul poate provoca tulburări de spectru autist și scăderea coeficientului intelectual."},{"id":"E","text":"Cefalosporinele fac parte din clasa C de risc teratogen și sunt contraindicate pe durata sarcinii."}],"correct":["A","B","D"],"pages":[575,576,577],"source":"set-2"},{"id":"set2-pc-2XFlI","fingerprint":"3bcc26644d733dd5","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Sindromul de compresie a venei cave inferioare și modificările adaptative materne pe parcursul sarcinii prezintă anumite caracteristici clinice și terapeutice. Care dintre următoarele enunțuri sunt corecte?","options":[{"id":"A","text":"În primul trimestru de sarcină, gravidele pot prezenta sincope determinate de hiperoxigenarea cerebrală indusă de vasoconstricția sistemică."},{"id":"B","text":"Compresiunea venei cave inferioare apare cel mai frecvent în decubit lateral stâng, ducând la reducerea debitului cardiac."},{"id":"C","text":"Manifestările clinice ale compresiunii vasculare în decubit dorsal includ hipotensiune, tahicardie, amețeală și senzație acută de lipsă de aer."},{"id":"D","text":"Majoritatea urgențelor dento-parodontale apar în trimestrul al II-lea al sarcinii, când starea gravidei se deteriorează progresiv."},{"id":"E","text":"Plasarea pacientei în decubit lateral stâng reprezintă tratamentul de urgență pentru creșterea volumului vascular cerebral."}],"correct":["C","E"],"pages":[575,576,577],"source":"set-2"},{"id":"set2-7QlT2EEs","fingerprint":"760c49ccd194e163","chapterId":"set-2","subchapterId":"set2-7.05","type":"CS","text":"Din perspectiva modificărilor fiziologice și a investigațiilor imagistice asociate sarcinii, se constată următoarele fenomene:","options":[{"id":"A","text":"Timpul de înjumătățire plasmatică al medicamentelor este prelungit pe perioada sarcinii."},{"id":"B","text":"O radiografie retroalveolară expune fătul la o doză de radiații de 0,01 rad."},{"id":"C","text":"Pentru a produce mutații sau retard mental, doza de radiații la care este expus fătul trebuie să depășească 10 mrad."},{"id":"D","text":"Solubilitatea lipidică și viteza de eliminare a substanțelor medicamentoase sunt crescute."},{"id":"E","text":"Volumul de distribuție al medicamentului este semnificativ redus."}],"correct":["D"],"pages":[575,576,577],"source":"set-2"},{"id":"set2-LSGOYxlF","fingerprint":"fd096e983c068438","chapterId":"set-2","subchapterId":"set2-7.05","type":"CM","text":"Efectuarea extracțiilor dentare la gravide impune anumite măsuri de precauție privind programarea și controlul stresului. Care dintre următoarele aspecte descriu un management adecvat al acestor intervenții?","options":[{"id":"A","text":"Se recomandă amânarea tratamentelor dento-parodontale de rutină în primul și în ultimul trimestru de sarcină, limitându-se exclusiv la rezolvarea urgențelor."},{"id":"B","text":"Gravidele cu risc de aspirație a resturilor radiculare vor fi tratate în decubit dorsal pentru o mai bună vizibilitate."},{"id":"C","text":"Efectele cumulate ale adrenalinei din anestezic și ale fricii resimțite de pacientă determină creșterea marcată a circulației feto-placentare."},{"id":"D","text":"Sumarea catecolaminelor endogene eliberate în timpul stresului cu cele exogene poate duce la tahicardie reflexă a fătului și la declanșarea precoce a travaliului."},{"id":"E","text":"Gravidele cu tendință de vomă se programează pentru tratament la primele ore ale dimineții pentru a evita diskineziile digestive postprandiale."}],"correct":["A","D"],"pages":[575,576,577],"source":"set-2"}];
